mapper.select:
select t2.*
from(select t1.*,
(
select s.DESCRIPTION
from sys_user s
where s.user_id =  t1.confirm_Person
) as confirm_person_n,
(
select sc.meaning value_name
from sys_code_value_b_v sc
where sc.code = 'INSURE_STATUS'
and sc.code_value = t1.insured_status
) as insured_status_n,
(
select sc.meaning value_name
from sys_code_value_b_v sc
where sc.code = 'POLICY_STATUS'
and sc.code_value = t1.policy_status
) as policy_status_n,
(select pp.contract_number from prj_project pp where pp.project_id = t1.project_id) contract_number,
(select pp.contract_name from prj_project pp where pp.project_id = t1.project_id) contract_name,
(select p1.plan_number from jc_insurance_plan p1 where p1.plan_id = t1.plan_id)plan_number,
(SELECT b.bp_name FROM hls_bp_master b, prj_project ppt WHERE b.bp_id = ppt.tenant_id AND ppt.project_id =
t1.project_id ) bp_name,
(select pp.contract_amount from prj_project pp where pp.project_id = t1.project_id) contract_amount,
(select pp.finance_amount from prj_project pp where pp.project_id = t1.project_id) finance_amount,
(case when (select count(1) from prj_insure_settlement_list pl where pl.INSURE_ID = t1.INSURE_ID) > 0 then 'Y'
else 'N' end)settlement_yn,
(select pp.contract_number from prj_project pp where pp.project_id = t1.project_id)project_id_n,
(select a.plan_number from jc_insurance_plan a where a.plan_id = t1.plan_id)plan_id_n
from PRJ_PROJECT_INSURE t1
)t2
where 1 = 1

    and t2.project_id = #{projectId}


    and t2.contract_name = #{contractName}


    and t2.bp_name = #{bpName}


    and t2.insure_number = #{insureNumber}


    and t2.insure_start_date >= #{insureFrom}


    and t2.insure_start_date <= #{insureTo}


    and t2.settlement_yn = #{settlement_yn}


    and t2.policy_status = #{policyStatus}


    and t2.insured_status = #{insuredStatus}

SELECT t2.* FROM ( SELECT t1.*, ( SELECT sc.meaning value_name FROM sys_code_value_b_v sc WHERE sc.CODE = 'INSURE_STATUS' AND sc.code_value = t1.insured_status ) AS insured_status_n, ( SELECT sc.meaning value_name FROM sys_code_value_b_v sc WHERE sc.CODE = 'POLICY_STATUS' AND sc.code_value = t1.policy_status ) AS policy_status_n, pp.contract_number, pp.contract_name, p1.plan_number, b.bp_name, pp.contract_amount, pp.finance_amount, ( CASE
WHEN ( SELECT count( 1 ) FROM prj_insure_settlement_list pl WHERE pl.INSURE_ID = t1.INSURE_ID ) > 0 THEN 'Y' ELSE 'N' END ) settlement_yn, pp.contract_number project_id_n, p1.plan_number plan_id_n, ( SELECT sc.meaning value_name FROM sys_code_value_b_v sc WHERE sc.CODE = 'BENEFICIARY_TYPE' AND sc.code_value = t.BENEFICIARY_TYPE ) BENEFICIARY_TYPE_N, t.BENEFICIARY_ID, t.BENEFICIARY_TYPE, t.BENEFICIARY_NAME, t.BENEFICIARY_NUMBER, t.BENEFICIARY_NOTE FROM PRJ_PROJECT_INSURE t1 LEFT JOIN prj_insure_beneficiary t ON t1.INSURE_ID = t.INSURE_ID LEFT JOIN prj_project pp ON pp.PROJECT_ID = t1.project_id LEFT JOIN hls_bp_master b ON b.bp_id = pp.tenant_id LEFT JOIN jc_insurance_plan p1 ON p1.plan_id = t1.plan_id ) t2 where 1 = 1
and t2.project_id = #{projectId}
and t2.contract_name = #{contractName}
and t2.bp_name like concat('%',#{bpName},'%')
and t2.insure_number = #{insureNumber}
and t2.insure_start_date >= #{insureFrom}
and t2.insure_start_date <= #{insureTo}
and t2.settlement_yn = #{settlement_yn}
and t2.policy_status = #{policyStatus}
and t2.beneficiary_name like concat('%',#{beneficiaryName},'%')
and t2.beneficiary_type = #{beneficiaryType}
and t2.insured_status = #{insuredStatus}

select t2.*
from(select t1.*,
(
select sc.meaning value_name
from sys_code_value_b_v sc
where sc.code = 'INSURE_STATUS'
and sc.code_value = t1.insured_status
) as insured_status_n,
(
select sc.meaning value_name
from sys_code_value_b_v sc
where sc.code = 'POLICY_STATUS'
and sc.code_value = t1.policy_status
) as policy_status_n,
(select pp.contract_number from prj_project pp where pp.project_id = t1.project_id) contract_number,
(select pp.contract_name from prj_project pp where pp.project_id = t1.project_id) contract_name,
(select p1.plan_number from jc_insurance_plan p1 where p1.plan_id = t1.plan_id)plan_number,
(SELECT b.bp_name FROM hls_bp_master b, prj_project ppt WHERE b.bp_id = ppt.tenant_id AND ppt.project_id =
t1.project_id ) bp_name,
(select pp.contract_amount from prj_project pp where pp.project_id = t1.project_id) contract_amount,
(select pp.finance_amount from prj_project pp where pp.project_id = t1.project_id) finance_amount,
(case when (select count(1) from prj_insure_settlement_list pl where pl.INSURE_ID = t1.INSURE_ID) > 0 then 'Y'
else 'N' end)settlement_yn,
(select pp.contract_number from prj_project pp where pp.project_id = t1.project_id)project_id_n
from PRJ_PROJECT_INSURE t1
)t2
where t2.policy_status = 'HANDOVING'

    and t2.project_id = #{projectId}


    and t2.contract_name = #{contractName}


    and t2.bp_name = #{bpName}


    and t2.insure_number = #{insureNumber}


    and t2.insure_start_date = #{insureFrom}


    and t2.insure_start_date = #{insureTo}


    and t2.settlement_yn = #{settlement_yn}


    and t2.policy_status = #{policyStatus}

select t.insure_id, t.project_id, (select pp.contract_number from prj_project pp where pp.project_id = t.project_id) contract_number, (select pp.contract_name from prj_project pp where pp.project_id = t.project_id) contract_name, t.insure_category, nvl(t.insure_amount, 0) insure_amount, t.insure_end_date, t.description, t.insure_company, t.creation_date add_date, t.beneficiary_change, t.xy_lease_item, t.consistent_flag, t.approval_status, (select v.meaning from sys_code_value_b_v v where v.code = 'SYS.YES_NO' and v.code_value = t.beneficiary_change) as beneficiary_change_n, (select v.meaning from sys_code_value_b_v v where v.code = 'SYS.YES_NO' and v.code_value = t.xy_lease_item) as xy_lease_item_n, (select v.meaning from sys_code_value_b_v v where v.code = 'SYS.YES_NO' and v.code_value = t.consistent_flag) as consistent_flag_n from PRJ_PROJECT_INSURE t
t.project_id = #{projectId}
and t.insure_id = #{insureId}
and t.APPROVAL_STATUS = #{approvalStatus}
and t.ADD_FLAG = #{addFlag}
